from __future__ import annotations

"""G5:R3 generic endpoint-typed recursive hidden-message law.

This is a non-promoting post-graduation structural stage.  R2 established that
no fixed finite local truncation depth is globally sufficient for the frozen
exact-child observer.  R3 asks the constructive next question: whether the
*complete* endpoint-typed rooted cavity message is generated by one fixed local
recursion on every finite hidden tree and whether exact hidden-canon equality is
stable under arbitrary finite continuations of the certified relation-valued
leaf-graft algebra.

Exact scientific equality is structural tuple equality.  Digests are audit
handles only.
"""

from collections import deque
from importlib.resources import files
from itertools import product
from pathlib import Path
from typing import Any, Iterable, Mapping, Sequence
import json

from .canon import canonical_sha256
from .adapters.g4_accepted import G4AcceptedAdapter, DecoratedG4Tree
from .typed_tree_messages import prepare_endpoint_decorated_tree
from .uplift_g3_r1 import _generate_tree_shapes


class G5R3Error(RuntimeError):
    pass


_SPEC = "G5_R3_GENERIC_ENDPOINT_TYPED_MESSAGE_CONGRUENCE_SPEC_V1.json"


def _resource(name: str) -> Path:
    return Path(str(files("infinity_grid").joinpath("resources/uplift").joinpath(name)))


def r3_spec() -> dict[str, Any]:
    obj = json.loads(_resource(_SPEC).read_text(encoding="utf-8"))
    if obj.get("schema_id") != "IG_G5_R3_GENERIC_ENDPOINT_TYPED_MESSAGE_CONGRUENCE_SPEC_V1":
        raise G5R3Error("bad G5:R3 spec schema")
    payload = {k: v for k, v in obj.items() if k != "science_sha256"}
    if canonical_sha256(payload) != obj.get("science_sha256"):
        raise G5R3Error("G5:R3 spec hash mismatch")
    return obj


def verify_authority(
    r2_primary: Mapping[str, Any],
    r2_verification: Mapping[str, Any],
    r2_closeout: Mapping[str, Any],
) -> dict[str, Any]:
    s = r3_spec(); a = s["authority"]; failures: list[str] = []
    if r2_primary.get("schema_id") != "IG_G5_R2_PREDICTIVE_HIDDEN_ACTION_READ_RESULT_V1" or r2_primary.get("status") != "PASS":
        failures.append("R2_PRIMARY_SCHEMA_OR_STATUS")
    if str(r2_primary.get("classification")) != str(a["required_r2_classification"]):
        failures.append("R2_CLASSIFICATION")
    if str(r2_primary.get("science_sha256")) != str(a["g5_r2_primary_science_sha256"]):
        failures.append("R2_PRIMARY_IDENTITY")
    if r2_primary.get("exact_reference_hidden_read") != a["required_r2_exact_reference_hidden_read"]:
        failures.append("R2_REFERENCE_READ")
    if r2_primary.get("g5_graduation_preserved") is not True or r2_primary.get("promotion") is not False:
        failures.append("R2_FIREWALL")
    if r2_primary.get("global_fixed_depth_lower_bound", {}).get("global_fixed_finite_local_depth_sufficient") is not False:
        failures.append("R2_FIXED_DEPTH_LOWER_BOUND")
    if r2_verification.get("status") != "PASS" or str(r2_verification.get("verification_sha256")) != str(a["g5_r2_independent_verification_sha256"]):
        failures.append("R2_VERIFICATION")
    if r2_closeout.get("schema_id") != "IG_G5_R2_CERTIFIED_CLOSEOUT_V1" or r2_closeout.get("status") != "CERTIFIED_PASS":
        failures.append("R2_CLOSEOUT_STATUS")
    if str(r2_closeout.get("closeout_sha256")) != str(a["g5_r2_closeout_sha256"]):
        failures.append("R2_CLOSEOUT_IDENTITY")
    out = {
        "schema_id": "IG_G5_R3_AUTHORITY_CHECK_V1",
        "status": "PASS" if not failures else "FAIL",
        "failures": failures,
        "r2_primary_science_sha256": r2_primary.get("science_sha256"),
        "r2_verification_sha256": r2_verification.get("verification_sha256"),
        "r2_closeout_sha256": r2_closeout.get("closeout_sha256"),
        "r2_exact_reference_hidden_read": r2_primary.get("exact_reference_hidden_read"),
        "public_descriptor": a["required_public_descriptor"],
        "g5_graduation_preserved": True,
        "promotion": False,
    }
    out["science_sha256"] = canonical_sha256(out)
    if failures:
        raise G5R3Error("R2 authority mismatch: " + ",".join(failures))
    return out


# ---------------------------------------------------------------------------
# Independent structural oracle used by the R3 support panel.  It deliberately
# does not call typed_tree_messages or the adapter's canon methods.
# ---------------------------------------------------------------------------

def _freeze(value: Any) -> tuple[Any, ...]:
    if value is None: return ("null",)
    if isinstance(value, bool): return ("bool", bool(value))
    if isinstance(value, int): return ("int", int(value))
    if isinstance(value, float): return ("float", value.hex())
    if isinstance(value, str): return ("str", value)
    if isinstance(value, bytes): return ("bytes", value.hex())
    if isinstance(value, Mapping):
        return ("map", tuple(sorted((_freeze(k), _freeze(v)) for k, v in value.items())))
    if isinstance(value, (list, tuple)):
        return ("seq", tuple(_freeze(x) for x in value))
    raise G5R3Error(f"independent oracle unsupported label type {type(value).__name__}")


def _independent_adjacency(
    n: int,
    edges: Sequence[Sequence[int]],
    vertex_keys: Sequence[Any],
    endpoint_ops: Sequence[Sequence[Any]],
) -> tuple[list[list[tuple[int, tuple[Any, ...]]]], tuple[tuple[Any, ...], ...]]:
    n = int(n)
    if n < 1 or len(vertex_keys) != n or len(edges) != n - 1 or len(endpoint_ops) != n - 1:
        raise G5R3Error("independent oracle arity/tree-size failure")
    adj: list[list[tuple[int, tuple[Any, ...]]]] = [[] for _ in range(n)]
    seen: set[tuple[int,int]] = set()
    for e, op in zip(edges, endpoint_ops):
        if len(e) != 2 or len(op) != 2: raise G5R3Error("independent oracle edge/operator arity")
        u,v = int(e[0]), int(e[1]); a,b = op[0], op[1]
        if not (0 <= u < n and 0 <= v < n) or u == v: raise G5R3Error("independent oracle bad edge")
        k=(min(u,v),max(u,v))
        if k in seen: raise G5R3Error("independent oracle duplicate edge")
        seen.add(k)
        adj[u].append((v, _freeze((a,b))))
        adj[v].append((u, _freeze((b,a))))
    q=deque([0]); reached={0}
    while q:
        v=q.popleft()
        for u,_ in adj[v]:
            if u not in reached: reached.add(u); q.append(u)
    if len(reached)!=n: raise G5R3Error("independent oracle disconnected")
    return adj, tuple(_freeze(x) for x in vertex_keys)


def independent_rooted_canon(n:int, edges, vertex_keys, endpoint_ops, root:int) -> tuple[Any, ...]:
    adj, vlabs = _independent_adjacency(n, edges, vertex_keys, endpoint_ops)
    root=int(root)
    def rec(v:int,parent:int) -> tuple[Any,...]:
        children=tuple(sorted((lab,rec(u,v)) for u,lab in adj[v] if u!=parent))
        return ("V",vlabs[v],children)
    return rec(root,-1)


def independent_unrooted_canon(n:int, edges, vertex_keys, endpoint_ops) -> tuple[Any, ...]:
    return min(independent_rooted_canon(n,edges,vertex_keys,endpoint_ops,r) for r in range(int(n)))


def _eccentricity(n:int, edges:Sequence[Sequence[int]], root:int) -> int:
    adj=[[] for _ in range(int(n))]
    for e in edges:
        u,v=map(int,e);adj[u].append(v);adj[v].append(u)
    dist=[-1]*int(n);dist[int(root)]=0;q=deque([int(root)])
    while q:
        v=q.popleft()
        for u in adj[v]:
            if dist[u]<0:dist[u]=dist[v]+1;q.append(u)
    if min(dist)<0: raise G5R3Error("eccentricity on disconnected tree")
    return max(dist)


def _relabel_tree(tree: DecoratedG4Tree, perm: Sequence[int]) -> DecoratedG4Tree:
    if len(perm)!=tree.n or sorted(map(int,perm))!=list(range(tree.n)):
        raise G5R3Error("bad relabel permutation")
    p=list(map(int,perm))
    colors=[None]*tree.n
    for old,c in enumerate(tree.H_classes): colors[p[old]]=c
    edges=[];ops=[]
    for (u,v),op in zip(tree.edges,tree.edge_operators):
        edges.append((p[u],p[v]));ops.append(tuple(op))
    return DecoratedG4Tree(tree.n,tuple(edges),tuple(colors),tuple(ops))


def _manual_graft_children(ad:G4AcceptedAdapter, tree:DecoratedG4Tree, *, new_H:str, op:Sequence[int]) -> list[DecoratedG4Tree]:
    op=tuple(map(int,op))
    if op not in set(ad.operator_basis()): raise G5R3Error("manual graft operator outside basis")
    local=[list(map(int,ad._rows[k]["caps7"])) for k in tree.H_classes]
    for (u,v),(a,b) in zip(tree.edges,tree.edge_operators): local[u][a]-=1;local[v][b]-=1
    new_caps=list(map(int,ad._rows[str(new_H)]["caps7"]))
    out=[]
    for root in range(tree.n):
        if local[root][op[0]]<=0 or new_caps[op[1]]<=0: continue
        out.append(DecoratedG4Tree(tree.n+1,tree.edges+((root,tree.n),),tree.H_classes+(str(new_H),),tree.edge_operators+(op,)))
    return out


def _relation_children(ad:G4AcceptedAdapter, tree:DecoratedG4Tree, *, new_H:str, op:Sequence[int]) -> dict[tuple[Any,...],DecoratedG4Tree]:
    out={}
    for root in range(tree.n):
        for child in ad.graft_relation(tree,root,new_H_class=str(new_H),operator=tuple(map(int,op))):
            out.setdefault(ad.unrooted_canon(child),child)
    return out


def _future_relation_set(ad:G4AcceptedAdapter, tree:DecoratedG4Tree, word:Sequence[Sequence[Any]]) -> tuple[tuple[Any,...], ...]:
    current={ad.unrooted_canon(tree):tree}
    for payload in word:
        new_H=str(payload[0]);op=tuple(map(int,payload[1]));nxt={}
        for t in current.values():
            for c,child in _relation_children(ad,t,new_H=new_H,op=op).items():nxt.setdefault(c,child)
        current=nxt
    return tuple(sorted(current.keys()))


def _manual_future_relation_set(ad:G4AcceptedAdapter, tree:DecoratedG4Tree, word:Sequence[Sequence[Any]]) -> tuple[tuple[Any,...], ...]:
    current={independent_unrooted_canon(tree.n,tree.edges,[ad._vertex_key(x) for x in tree.H_classes],tree.edge_operators):tree}
    for payload in word:
        new_H=str(payload[0]);op=tuple(map(int,payload[1]));nxt={}
        for t in current.values():
            for child in _manual_graft_children(ad,t,new_H=new_H,op=op):
                can=independent_unrooted_canon(child.n,child.edges,[ad._vertex_key(x) for x in child.H_classes],child.edge_operators)
                nxt.setdefault(can,child)
        current=nxt
    return tuple(sorted(current.keys()))


