def exhaustive_support_panel() -> dict[str, Any]:
    s=r3_spec()["support_panel"];ad=G4AcceptedAdapter();shapes=_generate_tree_shapes(4)
    palette=[tuple(map(int,x)) for x in s["existing_edge_operator_palette"]]
    expected_shapes={1:1,2:1,3:1,4:2}
    rows=[];total_parents=0;rooted_cases=0;future_word_checks=0;failures=[]
    for n in range(1,5):
        if len(shapes[n])!=expected_shapes[n]: failures.append(f"SHAPE_COUNT_N{n}")
        nparents=0;nroots=0;nfuture=0
        for edges in shapes[n].values():
            for colors in product(tuple(s["vertex_H_palette"]),repeat=n):
                edge_products=[tuple()] if n==1 else product(palette,repeat=n-1)
                for ops in edge_products:
                    tree=DecoratedG4Tree(n,tuple(edges),tuple(colors),tuple(ops))
                    pub=ad.public_read(tree)
                    if not pub.get("legal"): failures.append(f"UNEXPECTED_ILLEGAL_PARENT_N{n}");continue
                    nparents+=1;total_parents+=1
                    keys=[ad._vertex_key(x) for x in tree.H_classes]
                    prep=prepare_endpoint_decorated_tree(tree.n,tree.edges,keys,tree.edge_operators)
                    impl_u=prep.unrooted_canon();ind_u=independent_unrooted_canon(tree.n,tree.edges,keys,tree.edge_operators)
                    if impl_u!=ind_u: failures.append(f"UNROOTED_ORACLE_N{n}")
                    for root in range(n):
                        nroots+=1;rooted_cases+=1
                        impl=prep.rooted_canon(root);ind=independent_rooted_canon(tree.n,tree.edges,keys,tree.edge_operators,root)
                        if impl!=ind: failures.append(f"ROOTED_ORACLE_N{n}")
                        ecc=_eccentricity(tree.n,tree.edges,root)
                        if prep.rooted_truncated(root,ecc)!=impl: failures.append(f"ECC_BOUND_N{n}")
                    perm=tuple(reversed(range(n)))
                    rel=_relabel_tree(tree,perm)
                    if ad.unrooted_canon(rel)!=ad.unrooted_canon(tree): failures.append(f"RELABEL_CANON_N{n}")
                    if ad.public_read(rel)!=pub: failures.append(f"RELABEL_PUBLIC_N{n}")
                    for word in s["payload_words"]:
                        a=_future_relation_set(ad,tree,word);b=_future_relation_set(ad,rel,word);m=_manual_future_relation_set(ad,tree,word)
                        nfuture+=1;future_word_checks+=1
                        if a!=b: failures.append(f"RELABEL_FUTURE_N{n}")
                        if a!=m: failures.append(f"INDEPENDENT_FUTURE_N{n}")
        rows.append({"n":n,"unlabelled_shape_count":len(shapes[n]),"decorated_parent_count":nparents,"rooted_canon_cases":nroots,"future_word_checks":nfuture})
    # Exact preregistered combinatorial counts for this palette/scope.
    expected_parents=2+12+72+864
    expected_roots=2+24+216+3456
    expected_future=expected_parents*len(s["payload_words"])
    if total_parents!=expected_parents: failures.append(f"PARENT_COUNT:{total_parents}")
    if rooted_cases!=expected_roots: failures.append(f"ROOT_COUNT:{rooted_cases}")
    if future_word_checks!=expected_future: failures.append(f"FUTURE_COUNT:{future_word_checks}")
    out={
      "schema_id":"IG_G5_R3_EXHAUSTIVE_SUPPORT_PANEL_V1","status":"PASS" if not failures else "FAIL",
      "scope":{"n_min":1,"n_max":4,"vertex_H_palette":s["vertex_H_palette"],"existing_edge_operator_palette":s["existing_edge_operator_palette"],"payload_words":s["payload_words"]},
      "rows":rows,"decorated_parent_count":total_parents,"rooted_canon_case_count":rooted_cases,"future_word_check_count":future_word_checks,
      "expected_parent_count":expected_parents,"expected_rooted_case_count":expected_roots,"expected_future_word_check_count":expected_future,
      "independent_structural_oracle_used":True,"relabelling_invariance_checked":True,"public_read_invariance_checked":True,
      "structural_equality_used":True,"digest_only_equality_used":False,"failures":failures[:50]
    }
    out["science_sha256"]=canonical_sha256(out)
    if failures: raise G5R3Error("support panel failed: "+",".join(failures[:10]))
    return out


def all_operator_sentinel() -> dict[str, Any]:
    ad=G4AcceptedAdapter();ops=list(ad.operator_basis());failures=[];rows=[]
    if len(ops)!=31: failures.append("OPERATOR_BASIS_SIZE")
    for op in ops:
        a,b=op
        t=DecoratedG4Tree(2,((0,1),),("C","D"),(op,))
        rev=DecoratedG4Tree(2,((1,0),),("C","D"),((b,a),))
        can=ad.unrooted_canon(t);can_rev=ad.unrooted_canon(rev)
        if can!=can_rev: failures.append(f"STORAGE_REVERSAL:{a}>{b}")
        asym=None
        if a!=b:
            swapped=DecoratedG4Tree(2,((0,1),),("C","D"),((b,a),))
            asym=ad.unrooted_canon(swapped)!=can
            if not asym: failures.append(f"ASYMMETRIC_COLLAPSE:{a}>{b}")
        # Relabel both endpoints and transport the edge storage without changing
        # endpoint positions inside the stored operator tuple.
        rel=_relabel_tree(t,(1,0))
        if ad.unrooted_canon(rel)!=can: failures.append(f"RELABEL_CANON:{a}>{b}")
        for root in (0,1):
            ch=ad.graft_relation(t,root,new_H_class="C",operator=(0,0))
            chr_=ad.graft_relation(rel,1-root,new_H_class="C",operator=(0,0))
            ca=tuple(sorted(ad.unrooted_canon(x) for x in ch));cb=tuple(sorted(ad.unrooted_canon(x) for x in chr_))
            if ca!=cb: failures.append(f"GRAFT_RELABEL:{a}>{b}:{root}")
        rows.append({"operator":[a,b],"storage_reversal_equal":can==can_rev,"asymmetric_endpoint_assignment_distinguished":asym,"relabel_graft_transport_pass":True})
    out={"schema_id":"IG_G5_R3_ALL_31_OPERATOR_MESSAGE_SENTINEL_V1","status":"PASS" if not failures else "FAIL","operator_count":len(ops),"rows":rows,"failures":failures,"endpoint_direction_semantics_preserved":not failures}
    out["science_sha256"]=canonical_sha256(out)
    if failures: raise G5R3Error("all-operator sentinel failed: "+",".join(failures[:8]))
    return out


def r2_bridge(r2_primary: Mapping[str,Any]) -> dict[str,Any]:
    lower=r2_primary.get("global_fixed_depth_lower_bound",{})
    pA=r2_primary.get("fresh_n8_color_panel",{});pB=r2_primary.get("endpoint_typed_n5_panel",{})
    failures=[]
    if lower.get("global_fixed_finite_local_depth_sufficient") is not False: failures.append("LOWER_BOUND")
    if int(pA.get("first_predictive_depth",-1))!=6 or pA.get("nontrivial_reduction_candidate_survived") is not False: failures.append("N8_BRIDGE")
    if int(pB.get("first_predictive_depth",-1))!=4 or pB.get("nontrivial_reduction_candidate_survived") is not False: failures.append("N5_BRIDGE")
    if pA.get("structural_equality_used") is not True or pB.get("structural_equality_used") is not True: failures.append("EXACTNESS_BRIDGE")
    out={"schema_id":"IG_G5_R3_R2_RESULT_BRIDGE_V1","status":"PASS" if not failures else "FAIL","r2_primary_science_sha256":r2_primary.get("science_sha256"),"fixed_depth_global_sufficiency":False,"fresh_n8_first_predictive_depth":pA.get("first_predictive_depth"),"endpoint_n5_first_predictive_depth":pB.get("first_predictive_depth"),"no_nontrivial_local_compression_on_both_registered_panels":not failures,"failures":failures}
    out["science_sha256"]=canonical_sha256(out)
    if failures: raise G5R3Error("R2 bridge failed: "+",".join(failures))
    return out


def run_g5_r3_generic_message_congruence(*, engine:Any, r2_primary:Mapping[str,Any], r2_verification:Mapping[str,Any], r2_closeout:Mapping[str,Any]) -> dict[str,Any]:
    s=r3_spec();auth=verify_authority(r2_primary,r2_verification,r2_closeout);bridge=r2_bridge(r2_primary)
    theorem=theorem_certificate();panel=exhaustive_support_panel();sentinel=all_operator_sentinel()
    classification="G5_R3_GENERIC_ENDPOINT_TYPED_CAVITY_CANON_AND_FINITE_GRAFT_FUTURE_CONGRUENCE_EARNED_R2_FIXED_DEPTH_LOWER_BOUND_PRESERVED_NO_PROMOTION_R4_DESIGN_AUTHORIZED"
    out={
      "schema_id":"IG_G5_R3_GENERIC_ENDPOINT_TYPED_MESSAGE_CONGRUENCE_RESULT_V1","status":"PASS","stage_ref":"G5:R3","classification":classification,
      "promotion":False,"g5_graduation_preserved":True,"g6_started":False,"authority":auth,"r2_bridge":bridge,"generic_message_theorem":theorem,"exhaustive_support_panel":panel,"all_operator_sentinel":sentinel,
      "exact_reference_hidden_read":"ENDPOINT_TYPED_DECORATED_TREE_CANON","generic_recursive_hidden_message":"NONBACKTRACKING_ENDPOINT_TYPED_DECORATED_CAVITY_MESSAGE_CANON","finite_future_congruence_earned":True,
      "compact_hidden_read_promoted":False,"topology_promoted":False,"public_descriptor_changed":False,"next_authorized_stage":"G5:R4_DESIGN_AFTER_HUMAN_REVIEW","cost_control":s["cost_control"],"nonclaims":s["nonclaims"]
    }
    out["science_sha256"]=canonical_sha256(out);return out


def stable_payload(result:Mapping[str,Any])->dict[str,Any]:
    return {k:v for k,v in result.items() if k not in {"source_sha256","source_version","registry_sha256","execution_metadata"}}


def compare_cold_replay(primary:Mapping[str,Any], cold:Mapping[str,Any])->dict[str,Any]:
    p=canonical_sha256(stable_payload(primary));c=canonical_sha256(stable_payload(cold));fail=[]
    if primary.get("science_sha256")!=cold.get("science_sha256"):fail.append("SCIENCE_SHA")
    if primary.get("classification")!=cold.get("classification"):fail.append("CLASSIFICATION")
    if p!=c:fail.append("STABLE_PAYLOAD")
    out={"schema_id":"IG_G5_R3_COLD_REPLAY_COMPARISON_V1","status":"PASS" if not fail else "FAIL","certification":"CERTIFIED_PASS" if not fail else "CERTIFICATION_FAILED","failures":fail,"primary_science_sha256":primary.get("science_sha256"),"cold_science_sha256":cold.get("science_sha256"),"stable_scientific_payload_exact_equal":p==c,"stable_scientific_payload_sha256":p}
    out["comparison_sha256"]=canonical_sha256(out);return out


def certified_closeout(primary:Mapping[str,Any],cold:Mapping[str,Any],comparison:Mapping[str,Any],independent:Mapping[str,Any])->dict[str,Any]:
    ok=primary.get("status")=="PASS" and cold.get("status")=="PASS" and comparison.get("certification")=="CERTIFIED_PASS" and independent.get("status")=="PASS"
    out={"schema_id":"IG_G5_R3_CERTIFIED_CLOSEOUT_V1","status":"CERTIFIED_PASS" if ok else "CERTIFICATION_FAILED","experiment_id":"G5:R3.GENERIC_ENDPOINT_TYPED_MESSAGE_CONGRUENCE","classification":primary.get("classification") if ok else "G5_R3_REVIEW_REQUIRED_NO_PROMOTION","science_sha256":primary.get("science_sha256"),"stable_science_payload_sha256":comparison.get("stable_scientific_payload_sha256"),"comparison_sha256":comparison.get("comparison_sha256"),"independent_verification_sha256":independent.get("verification_sha256"),"source_sha256":primary.get("source_sha256"),"registry_sha256":primary.get("registry_sha256"),"promotion":False,"g5_graduation_preserved":True,"finite_future_congruence_earned":bool(primary.get("finite_future_congruence_earned")) if ok else False,"compact_hidden_read_promoted":False,"topology_promoted":False,"g6_started":False,"next_authorized_stage":"G5:R4_DESIGN_AFTER_HUMAN_REVIEW" if ok else None,"failures":comparison.get("failures",[])}
    out["closeout_sha256"]=canonical_sha256(out);return out
